css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-bq{width:min(900px,100%);display:grid;gap:2.2em;justify-items:start}
.fx-bq .mark{font:600 7em/.6 var(--font-heading);color:var(--accent);height:.5em}
.fx-bq blockquote{margin:0;font:500 clamp(1.7em,4.6vw,3em)/1.2 var(--font-heading);letter-spacing:-.015em}
.fx-bq mark{background:linear-gradient(transparent 62%,color-mix(in srgb,var(--accent) 38%,transparent) 62%);color:inherit;padding:0 .05em}
.fx-bq figcaption{display:flex;align-items:center;gap:1em}
.fx-bq .av{width:3.4em;height:3.4em;border-radius:50%}.fx-bq .av::before,.fx-bq .av::after{display:none}
.fx-bq figcaption b{display:block}.fx-bq figcaption small{opacity:.62}
.fx-bq .res{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1px;width:100%;border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;background:var(--border)}
.fx-bq .res div{background:color-mix(in srgb,var(--surface) 94%,var(--text));padding:1.1em 1.3em}.fx-bq .res b{display:block;font:600 1.8em/1.1 var(--font-heading);color:var(--primary)}.fx-bq .res span{font-size:.85em;opacity:.65}
@media(max-width:560px){.fx-bq .res{grid-template-columns:1fr}.fx-bq .mark{font-size:5em}}
